static inline TSNode ts_node__next_sibling(TSNode self, bool include_anonymous) {
  TSNode parent = ts_node_parent(self);
  TSNode result = ts_node__null();
  if (ts_node_is_null(parent)) return result;

  // Match the node identity: byte positions cannot distinguish zero-width siblings.
  TSTreeCursor cursor = ts_tree_cursor_new(parent);
  bool found = false;
  if (ts_tree_cursor_goto_first_child(&cursor)) {
    do {
      TSNode child = ts_tree_cursor_current_node(&cursor);
      if (found && (include_anonymous || ts_node_is_named(child))) {
        result = child;
        break;
      }
      if (ts_node_eq(child, self)) found = true;
    } while (ts_tree_cursor_goto_next_sibling(&cursor));
  }
  ts_tree_cursor_delete(&cursor);
  return result;
}
